import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.CuEaBji2.js";const b=JSON.parse('{"title":"Emby / Jellyfin 反向代理与 HTTPS 配置","description":"使用 NRE 为 Emby 或 Jellyfin 配置域名反代和自动 HTTPS，验证播放与拖动进度，并排查连接失败、缓冲和中途断流。","frontmatter":{"title":"Emby / Jellyfin 反向代理与 HTTPS 配置","description":"使用 NRE 为 Emby 或 Jellyfin 配置域名反代和自动 HTTPS，验证播放与拖动进度，并排查连接失败、缓冲和中途断流。"},"headers":[],"relativePath":"guides/emby-jellyfin.md","filePath":"guides/emby-jellyfin.md","lastUpdated":1792150187000}'),r={name:"guides/emby-jellyfin.md"};function l(i,t,n,h,s,c){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="emby-jellyfin-反向代理与-https" tabindex="-1">Emby / Jellyfin 反向代理与 HTTPS <a class="header-anchor" href="#emby-jellyfin-反向代理与-https" aria-label="Permalink to &quot;Emby / Jellyfin 反向代理与 HTTPS&quot;">​</a></h1><p>将客户端连接地址换成自己的域名，由 NRE 节点转发到你有权访问的 Emby 或 Jellyfin 服务。电视和盒子可以直接使用这个域名，无需在客户端配置额外代理。</p><p>NRE 不负责媒体存储、刮削或转码。代理是否更快取决于「客户端 → 入口节点 → 后端」的实际线路与带宽，增加一跳并不保证加速。</p><h2 id="选择适合的接入方式" tabindex="-1">选择适合的接入方式 <a class="header-anchor" href="#选择适合的接入方式" aria-label="Permalink to &quot;选择适合的接入方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后端在哪里</th><th>接入方式</th></tr></thead><tbody><tr><td>有公网地址，VPS 可以直接访问</td><td>HTTP 规则填写后端 HTTP/HTTPS 地址</td></tr><tr><td>与节点在同一内网</td><td>填写节点可访问的内网 IP 和端口</td></tr><tr><td>在家中内网，VPS 无法直接访问</td><td>先接入内网 Agent，再按 <a href="./relay">Relay 指南</a> 配置；仅加入 Agent 不会自动打通业务流量</td></tr></tbody></table><p>初次使用先完成 <a href="./../getting-started/quickstart">快速开始</a> 的部署与登录。默认运行时是纯 Go，项目名称保留了历史上的 Nginx 字样；当前面板的转发行为不通过编辑 <code>nginx.conf</code> 调整。</p><h2 id="最小规则示例" tabindex="-1">最小规则示例 <a class="header-anchor" href="#最小规则示例" aria-label="Permalink to &quot;最小规则示例&quot;">​</a></h2><p>假设你的节点能访问 <code>http://192.168.1.100:8096</code>：</p><table tabindex="0"><thead><tr><th>字段</th><th>示例</th></tr></thead><tbody><tr><td>Agent</td><td>单机部署选 <code>local</code>；多节点选实际对外提供入口的节点</td></tr><tr><td>入口域名</td><td><code>https://media.example.com</code></td></tr><tr><td>后端地址</td><td><code>http://192.168.1.100:8096</code>，按实际部署替换</td></tr><tr><td>启用规则</td><td>开启</td></tr><tr><td>高级选项</td><td>先使用默认值，出现具体问题再调整</td></tr></tbody></table><p>将 <code>media.example.com</code> 的 DNS 指向入口节点，放行 TCP 80 / 443。保存后等待节点同步和证书签发，再用浏览器打开入口域名。面板自身使用另一个域名，例如 <code>panel.example.com</code>。</p><p>客户端服务器地址填写 <code>https://media.example.com</code>，账号仍然是媒体服务的账号，<strong>不是 NRE Panel token</strong>。如果服务设置了 URL 子路径，请同时核对客户端地址和 <a href="./http-rules">HTTP 规则</a> 的路径配置。</p><h2 id="验证是否真正可用" tabindex="-1">验证是否真正可用 <a class="header-anchor" href="#验证是否真正可用" aria-label="Permalink to &quot;验证是否真正可用&quot;">​</a></h2><p>只看到登录页还不够。请在实际使用的网络、客户端上检查：</p><ol><li><strong>登录与浏览</strong>：登录成功，海报、媒体库和详情能够加载。</li><li><strong>开始播放</strong>：播放常用格式的视频，确认画面、音轨和字幕。</li><li><strong>拖动进度</strong>：跳到影片中段后能继续播放，再测试暂停和恢复。</li><li><strong>持续播放</strong>：播放一段超过以往故障出现时长的视频，观察是否断流或跳到下一集。</li><li><strong>比较原站</strong>：条件允许时，同一客户端、同一影片分别直连与经过反代，区分原站或转码问题和转发路径问题。</li></ol><p>这些结果与客户端、媒体格式、后端和网络有关；一次连通性检查不能替代上述验证。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="页面能打开-播放却失败" tabindex="-1">页面能打开，播放却失败 <a class="header-anchor" href="#页面能打开-播放却失败" aria-label="Permalink to &quot;页面能打开，播放却失败&quot;">​</a></h3><p>先确认客户端确实使用入口域名。检查后端返回的播放地址是否跳转到了客户端无法访问的地址；涉及跳转时参考 <a href="./../operations/troubleshooting#何时关闭-302-307-重定向改写">重定向改写</a>。不要把带 token 或签名的完整播放 URL 粘贴到公开 Issue。</p><h3 id="拖动进度失败或播放中途断流" tabindex="-1">拖动进度失败或播放中途断流 <a class="header-anchor" href="#拖动进度失败或播放中途断流" aria-label="Permalink to &quot;拖动进度失败或播放中途断流&quot;">​</a></h3><p>先做相同视频的原站对比，并记录客户端版本、发生时间、影片码率和是否转码。NRE 的流式恢复依赖后端的 Range 支持及稳定的 <code>ETag</code> 或 <code>Last-Modified</code>，不能修复所有后端和网络问题。参见 <a href="./http-rules#流式恢复">流式恢复</a>。</p><h3 id="反代后仍缓冲或速度更慢" tabindex="-1">反代后仍缓冲或速度更慢 <a class="header-anchor" href="#反代后仍缓冲或速度更慢" aria-label="Permalink to &quot;反代后仍缓冲或速度更慢&quot;">​</a></h3><p>分别检查客户端到入口、入口到后端的线路。节点出口带宽、媒体码率、后端限速和转码性能都可能是瓶颈。先确认瓶颈，再决定是否换入口节点或使用出口代理。</p><h3 id="不知道问题在哪一段" tabindex="-1">不知道问题在哪一段 <a class="header-anchor" href="#不知道问题在哪一段" aria-label="Permalink to &quot;不知道问题在哪一段&quot;">​</a></h3><p>在运行规则的节点执行 <a href="./../operations/troubleshooting#只读连通性检查">只读连通性检查</a>。它区分 DNS、连接、TLS 与 HTTP 状态问题，但只检查当前机器直连，不测试视频、Relay、插件后端或规则自定义请求头。</p><p>仍需反馈时，请附上 NRE 版本/镜像标签、客户端与后端版本、部署方式、故障时间、原站对比结果和脱敏后的诊断输出。不要附上 <code>.env</code>、Panel token、证书私钥或完整播放链接。</p>',25)])])}const m=e(r,[["render",l]]);export{b as __pageData,m as default};
